
(function(){
  var c=document.getElementById('stars');if(!c)return;
  var ctx=c.getContext('2d'),W,H,pts=[];
  function resize(){W=c.width=c.offsetWidth;H=c.height=c.offsetHeight;}
  function mkPts(){pts=[];for(var i=0;i<130;i++)pts.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*.85+.15,a:Math.random(),da:(.002+Math.random()*.003)*(Math.random()<.5?1:-1)});}
  function draw(){ctx.clearRect(0,0,W,H);pts.forEach(function(p){p.a+=p.da;if(p.a>1||p.a<0)p.da*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba(140,160,255,'+p.a+')';ctx.fill();});requestAnimationFrame(draw);}
  resize();mkPts();draw();
  window.addEventListener('resize',function(){resize();mkPts();});
})();

