var currentCertType = null;

function openCertView(type) {
  var d = certData[type];
  if (!d || !certImages[type]) return;
  currentCertType = type;

  // Header
  document.getElementById('cvbLabel').textContent =
    type === 'python' ? 'Certificate of Completion' : 'Certificate of Participation';
  document.getElementById('cvbTitle').textContent = d.title;
  document.getElementById('cvbSub').textContent   = d.sub;

  // Image
  var imgWrap = document.getElementById('cvbImgWrap');
  imgWrap.innerHTML = '';
  var img = document.createElement('img');
  img.className = 'cvb-img';
  img.src = certImages[type];
  img.alt = d.title;
  imgWrap.appendChild(img);

  // Pills
  var meta = document.getElementById('cvbMeta');
  meta.innerHTML = '';
  d.pills.forEach(function(p) {
    var span = document.createElement('span');
    span.className = 'cvb-pill';
    span.textContent = p.label;
    span.style.cssText = 'color:' + p.color + ';background:' + p.bg + ';border:1px solid ' + p.border + ';';
    meta.appendChild(span);
  });

  // Save / download button
  var dlBtn = document.getElementById('cvbDownload');
  if (dlBtn) {
    dlBtn.onclick = function() {
      var a = document.createElement('a');
      a.href = certImages[type];
      a.download = d.title.replace(/[^a-z0-9]/gi, '_') + '.jpg';
      a.click();
    };
  }

  document.ge
  document.getElementById('certViewModal').classList.add('open');
}

function closeCertView(event) {
  if (!event || event.target === document.getElementById('certViewModal')) {
    document.getElementById('certViewModal').classList.remove('open');
  }
}

function closeResume(event) {
  if (!event || event.target === document.getElementById('resumeModal')) {
    document.getElementById('resumeModal').classList.remove('open');
  }
}

function handlePhoto(event) {
  var file = event.target.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    var img = document.getElementById('pImg');
    var ph = document.getElementById('pPh');
    img.src = e.target.result;
    img.style.display = 'block';
    ph.style.display = 'none';
  };
  reader.readAsDataURL(file);
}
